        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool reverted = false;
        try c.setOwner(a) {} catch { return; }
        assertTrue(c.owner() == a);
    }

    function testFuzz_run(address a, uint256 amount) public {
